import json, html, re
from pathlib import Path
from collections import Counter, defaultdict

W=Path(__file__).parent
O=Path('./artifacts/weekly-ui')
d=json.loads((W/'data.json').read_text('utf-8'))
e=lambda s:html.escape(str(s))
def badge(s):
    cls='good' if s in ('本地通过','展示通过') else ('bad' if s in ('本地不符','已证实规范差异') else 'wait')
    return f'<span class="badge {cls}">{e(s)}</span>'
def table(headers,rows):
    return '<div class="table-scroll"><table><thead><tr>'+''.join('<th>'+e(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def evidence_links(s):
    ids=re.findall(r'E\d{2}-[\w-]+',s)
    return ' · '.join(f'<a href="evidence/{e(x)}.jpg" target="_blank">{e(x)}</a>' for x in dict.fromkeys(ids)) or e(s or '本项无实测截图')
groups=defaultdict(list)
for row in d['scope']:
    if row['w2']=='UI/开':groups[row['level2']].append(row)
module_table=table(['业务区域','UI/开项','具体工作包','准入提示'],[[e(k),str(len(v)),'<br>'.join(e(x['seq']+' · '+x['feature']) for x in v),e('含原型条件项，先评审PRD' if any(x['source']!='PRD' for x in v) else '按用例准入列检查交互基线与业务页')] for k,v in groups.items()])
scope_table=table(['源序号 / 原表行','区域 / 工作包','来源 · 优先级','W2','本周工作 / 前置门槛','关联用例'],[[e(f"{x['seq']} / {x['row']}"),e(x['level2'])+'<br><strong>'+e(x['feature'])+'</strong>',e(x['source']+' · '+x['priority']),badge(x['w2']),e(x['action'])+'<br><span class="muted">'+e(x['gate'])+'</span>',e(x['case_ids'] or '不纳入本周UI执行')] for x in d['scope']])
issue_cards=[]
for x in d['issues']:
    issue_cards.append(f'''<article class="issue searchable" id="{e(x['id'])}" data-filter="{e(x['type'])}">
    <div class="item-top"><span class="item-id">{e(x['id'])} · {e(x['priority'])}</span>{badge(x['type'])}<span class="muted">{e(x['role'])}</span></div>
    <h3>{e(x['title'])}</h3><p><b>实际：</b>{e(x['actual'])}</p><p><b>修改或裁决：</b>{e(x['action'])}</p>
    <p class="accept"><b>复测判据：</b>{e(x['retest'])}</p><div class="meta">依据：{e(x['basis'])}<br>定位：{e(x['location'])}<br>关联：{e(x['cases'])} · {evidence_links(x['evidence'])}</div></article>''')
check_cards=[]
for x in d['templates']:
    check_cards.append(f'''<details class="check searchable" data-filter="{e(x['status'])}"><summary><span class="item-id">{e(x['id'])}</span><b>{e(x['title'])}</b>{badge(x['status'])}</summary>
    <div class="detail-body"><p><b>步骤：</b>{e(x['steps'])}</p><p><b>预期：</b>{e(x['expected'])}</p><p><b>本次观察：</b>{e(x['actual'])}</p>
    <div class="meta">依据：{e(x['basis'])} · 修改项：{e(x['issue'] or '无')}<br>{evidence_links(x['evidence'])}</div></div></details>''')
case_cards=[]
for x in d['business']:
    case_cards.append(f'''<details class="check searchable" data-filter="{e(x['status'])}"><summary><span class="item-id">{e(x['id'])}</span><b>{e(x['title'])}</b>{badge(x['status'])}</summary>
    <div class="detail-body"><div class="meta">{e(x['module'])} · {e(x['priority'])} · {e(x['kind'])} · 排期序号{e(x['seq'])}/原行{e(x['row'])}</div>
    <p><b>前提：</b>{e(x['precondition'])}</p><p><b>步骤：</b>{e(x['steps'])}</p><p><b>可观察预期：</b>{e(x['expected'])}</p>
    <p class="accept">执行结果：未执行。{e(x['evidence'])}。</p><div class="meta">依据：{e(x['basis'])}</div></div></details>''')
norm_table=table(['规范章节','维度','验收基线','关联检查 / 用例','修改项'],[[e(v) for v in x] for x in d['norm_rules']])
obs=json.loads((O/'evidence'/'observations.json').read_text('utf-8'))
observations={x['id']:x for x in obs}
gallery=[]
for f in sorted((O/'evidence').glob('*.jpg')):
    note=observations.get(f.stem,{}).get('note','首页与导航模板')
    gallery.append(f'<figure><a href="evidence/{e(f.name)}" target="_blank"><img loading="lazy" src="evidence/{e(f.name)}" alt="{e(f.stem)} {e(note)}"></a><figcaption><b>{e(f.stem)}</b><br>{e(note)}</figcaption></figure>')
counts=''.join(f'<span>{e(k)} <b>{v}</b></span>' for k,v in d['meta']['template_counts'].items())
def options(values):return '<option value="">全部状态</option>'+''.join(f'<option>{e(v)}</option>' for v in values)
